#include "ERA5DeClipperCore.hpp"
#include <iostream>
int main(){bool ok=true;std::cout<<"[";bool comma=false;for(double rate:{16000.,48000.,96000.}){dayu::ERA5DeClipperCore mono,stereo;mono.prepare(rate);stereo.prepare(rate);mono.setParameter(2,1);stereo.setParameter(2,1);std::array<float,257>input{},zero{},a{},b{},right{};float*mi[1]={input.data()},*mo[1]={a.data()},*si[2]={input.data(),zero.data()},*so[2]={b.data(),right.data()};uint64_t differences=0,crosstalk=0;const auto total=uint32_t(rate*.6);for(uint32_t t=0;t<total;t+=257){uint32_t n=std::min(257u,total-t);for(uint32_t i=0;i<n;++i){const double sec=(t+i)/rate;input[i]=float(std::clamp(.7*std::sin(2*M_PI*997*sec)+.2*std::sin(2*M_PI*301*sec),-.15,.25));}mono.process(mi,mo,1,n);stereo.process(si,so,2,n);for(unsigned i=0;i<n;++i){if(a[i]!=b[i])++differences;if(right[i]!=0)++crosstalk;}}if(comma)std::cout<<",";comma=true;std::cout<<"{\"rate\":"<<rate<<",\"monoStereoLeftDifferences\":"<<differences<<",\"silentRightNonzero\":"<<crosstalk<<",\"monoDeadlineMisses\":"<<mono.deadlineMisses()<<",\"stereoDeadlineMisses\":"<<stereo.deadlineMisses()<<"}";ok=ok&&differences==0&&crosstalk==0&&mono.deadlineMisses()==0&&stereo.deadlineMisses()==0;}std::cout<<"]\n";return !ok;}
